import { Controller, Get, Post, Body, Param, Delete, Req, UseGuards, Put, NotFoundException } from '@nestjs/common';
import { CustomerService } from './customer.service';
import { CreateCustomerDto, CreateCustomerResponseDto } from './dto/create-customer.dto';
import { Request } from 'express';
import {
    ApiBadRequestResponse,
    ApiBearerAuth,
    ApiCreatedResponse,
    ApiNotFoundResponse,
    ApiOkResponse,
    ApiOperation,
    ApiTags,
} from '@nestjs/swagger';
import { AuthGuard } from '@nestjs/passport';
import { UpdateCustomerDto } from './dto/update-customer.dto';
import { ReadCustomerResponseDTO, ReadCustomerResponseData } from './dto/read-customer.dto';
import { BasicResponseDTO } from '../basicResponseDTO';

@ApiBearerAuth('bearer')
@Controller('customers')
@ApiTags('Customers')
export class PublicAPICustomerController {
    constructor(readonly customerService: CustomerService) {}

    /**
     * List all customers created in this account
     */
    @ApiOkResponse({
        status: 200,
        description: 'OK',
        type: ReadCustomerResponseDTO,
    })
    @ApiBadRequestResponse({
        status: 400,
        description: 'Bad Request',
        type: BasicResponseDTO,
    })
    @ApiOperation({ operationId: 'Get all Customers' })
    @UseGuards(AuthGuard('jwt'))
    @Get()
    findAll(@Req() request: Request) {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        const { businessID } = request.user;
        return this.customerService.findAll({ businessID });
    }

    /**
     * Fine one customer
     */
    @ApiOkResponse({
        status: 200,
        description: 'OK',
        type: ReadCustomerResponseDTO,
    })
    @ApiBadRequestResponse({
        status: 400,
        description: 'Bad Request',
        type: BasicResponseDTO,
    })
    @ApiNotFoundResponse({
        status: 404,
        description: 'Customer Not Found',
        type: NotFoundException,
    })
    @ApiOperation({ operationId: 'Get a customer by ID' })
    @UseGuards(AuthGuard('jwt'))
    @Get(':customerId')
    findOne(@Param('customerId') customerId: string, @Req() request: Request) {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        const { businessID } = request.user;
        return this.customerService.findOne({ customerId, businessID });
    }

    /**
     * Create a customer
     */
    @ApiCreatedResponse({
        status: 201,
        description: 'Customer Created',
        type: CreateCustomerResponseDto,
    })
    @ApiBadRequestResponse({
        status: 400,
        description: 'Bad Request',
        type: BasicResponseDTO,
    })
    @ApiOperation({ operationId: 'Create a customer' })
    @UseGuards(AuthGuard('jwt'))
    @Post()
    create(@Body() createCustomerDto: CreateCustomerDto, @Req() request: Request) {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        const { businessID, sub } = request.user;
        console.log(JSON.stringify(createCustomerDto));
        return this.customerService.create({ ...createCustomerDto, businessID }, sub);
    }

    /**
     *  Update a customer
     */
    @ApiCreatedResponse({
        status: 201,
        description: 'Customer Updated',
        type: CreateCustomerDto,
    })
    @ApiBadRequestResponse({
        status: 400,
        description: 'Bad Request',
        type: BasicResponseDTO,
    })
    @ApiNotFoundResponse({
        status: 404,
        description: 'Customer Not Found',
        type: NotFoundException,
    })
    @Put(':customerId')
    @UseGuards(AuthGuard('jwt'))
    @ApiOperation({ operationId: 'Update a customer' })
    update(@Body() updateCustomerDto: UpdateCustomerDto, @Req() request: Request, @Param('customerId') customerId) {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        const { businessID } = request.user;
        return this.customerService.update({ ...updateCustomerDto, businessID, customerId });
    }

    /**
     * Delete a customer
     */
    @ApiOkResponse({
        status: 200,
        description: 'Customer Deleted',
        type: ReadCustomerResponseDTO,
    })
    @ApiNotFoundResponse({
        status: 404,
        description: 'Customer Not Found',
        type: NotFoundException,
    })
    @UseGuards(AuthGuard('jwt'))
    @Delete(':customerId')
    @ApiOperation({ operationId: 'Delete a customer' })
    remove(@Param('customerId') customerId: string, @Req() request: Request) {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        const { businessID } = request.user;
        return this.customerService.remove({ customerId, businessID });
    }
}

@ApiBearerAuth('bearer')
@Controller('customers')
@ApiTags('Customers')
export class PrivateAPICustomerController extends PublicAPICustomerController {}

import { Inject, Injectable, Logger, NotFoundException, forwardRef, ConflictException } from '@nestjs/common';
import { CreateCustomerDto, CreateCustomerResponseDto } from './dto/create-customer.dto';
import { InfluxService } from '../influx/influx.service';
import { CustomerEntity } from './entities/customer.entity';
import { v4 } from 'uuid';
import { UpdateCustomerDto } from './dto/update-customer.dto';
import { CustomerInvoiceMetadata, ReadCustomerResponseData } from './dto/read-customer.dto';
import { Invoice } from '../invoice/entities/invoice.entity';
import { SchedulerService } from '../scheduler/scheduler.service';
import { SchedulerStatus, SupportedMeasurementFrequencies, schedulerType } from '../scheduler/dto/scheduler.dto';
import { CronExpression } from '@nestjs/schedule';
import { ServicesService } from '../services/services.service';

@Injectable()
export class CustomerService {
    private static readonly logger = new Logger(CustomerService.name);
    constructor(
        readonly InfluxService: InfluxService,
        @Inject(forwardRef(() => SchedulerService)) readonly schedulerService: SchedulerService,
        @Inject(forwardRef(() => ServicesService)) readonly servicesService: ServicesService
    ) {}

    async create(createCustomerDto: CreateCustomerDto, subject: string): Promise<CreateCustomerResponseDto> {
        CustomerService.logger.log('Customer DTO', createCustomerDto);
        const customerId = v4();
        const { loadPoints } = this.InfluxService;
        const customerEntity = new CustomerEntity({ ...createCustomerDto, customerId });
        const points = CustomerEntity.transformer(customerEntity, this.InfluxService);
        CustomerService.logger.log('Points', points);
        await loadPoints(`${process.env.STAGE}-config`, `enterprise`, points);
        await this.schedulerService.create({
            schedulerID: customerId,
            schedulerType: schedulerType.billing,
            schedulerStatus: SchedulerStatus.live,
            scheduleParameters: { customerId, businessID: createCustomerDto.businessID },
            rate: SupportedMeasurementFrequencies.monthly,
            subject,
            businessID: createCustomerDto.businessID,
        });
        return { message: 'New customer added', customerId: customerEntity.customerId };
    }

    private async findInvoicesByCustomer({ businessID, customerId }) {
        CustomerService.logger.log(`Finding invoices for customer ${customerId} of business ${businessID}`);
        const invoiceDbModels = await this.InfluxService.getInvoicesForCustomer({ businessID, customerId });
        CustomerService.logger.debug(JSON.stringify(invoiceDbModels));
        if (invoiceDbModels.length > 0) {
            const responseData = invoiceDbModels.map(
                (dbModel) => new CustomerInvoiceMetadata(Invoice.fromDBModel(dbModel))
            );
            return { data: responseData, message: 'Found invoices for customer' };
        } else {
            return { data: [], message: 'No invoices found for customer' };
        }
    }

    async findAll({ businessID }): Promise<{ data: ReadCustomerResponseData[]; message: string }> {
        CustomerService.logger.log(`Finding customers for ${businessID}`);
        const customerDBModels = await this.InfluxService.getLatestCustomers({ businessID });
        if (customerDBModels.length > 0) {
            const response = [];
            for (let i = 0; i < customerDBModels.length; i++) {
                const dbModel = customerDBModels[i];
                const entity = CustomerEntity.dbModelToEntity(dbModel);
                const { customerId } = entity;
                const { data: invoices } = await this.findInvoicesByCustomer({
                    customerId,
                    businessID,
                });
                response.push(new ReadCustomerResponseData(entity, invoices));
            }
            return {
                data: response,
                message: 'Found Customers',
            };
        } else {
            return { data: [], message: 'No Customers Found' };
        }
    }

    async findOne({ customerId, businessID }): Promise<{ data: CustomerEntity[]; message: string }> {
        CustomerService.logger.log(`Finding saasClientID: ${customerId} for ${businessID}`);
        const customerConfig = await this.InfluxService.getLatestCustomer({ businessID, customerId });
        if (customerConfig.length > 0) {
            const { data: invoices } = await this.findInvoicesByCustomer({
                customerId,
                businessID,
            });
            return {
                data: [new ReadCustomerResponseData(CustomerEntity.dbModelToEntity(customerConfig[0]), invoices)],
                message: 'Found Customer',
            };
        } else {
            throw new NotFoundException(`Customer with ID: ${customerId} not found`);
        }
    }

    async remove({ customerId, businessID }): Promise<{ message: string; customerId: string }> {
        CustomerService.logger.log(`Attempting to delete customerId: ${customerId} for ${businessID}`);
        const customerConfig = await this.InfluxService.getLatestCustomer({ businessID, customerId });
        if (customerConfig.length === 0) {
            throw new NotFoundException(`Customer with ID: ${customerId} not found`);
        } else {
            const customerResults = await this.servicesService.findAllServicesWithCustomerId({
                customerId,
                businessID,
            });
            if (customerResults?.data?.length) {
                throw new ConflictException(
                    `Cannot delete customer when they are attached to services, delete services before deleting customer. Current serviceIds associated with the customer: ${customerResults.data.reduce(
                        (acc, { serviceId }) => {
                            acc += `${serviceId}   `;
                            return acc;
                        },
                        ''
                    )} `
                );
            }
            const { loadPoints } = this.InfluxService;
            const entity = CustomerEntity.dbModelToEntity(customerConfig[0]);
            entity.softDelete = true;
            entity.businessID = businessID;
            const points = CustomerEntity.transformer(entity, this.InfluxService);
            CustomerService.logger.log('Points to delete', points);
            try {
                await this.schedulerService.remove({ schedulerID: customerId, businessID, isBillingQueue: true });
            } catch (e) {
                if (e instanceof NotFoundException) {
                    CustomerService.logger.log(`Scheduler for customer ${customerId} not found`);
                } else {
                    throw e;
                }
            }
            await loadPoints(`${process.env.STAGE}-config`, `enterprise`, points);
        }
        return { message: 'Deleted Customer', customerId };
    }

    async update({ customerId, businessID, ...updatedFields }: UpdateCustomerDto): Promise<CreateCustomerResponseDto> {
        CustomerService.logger.log(`Attempting to update saasClientID: ${customerId} for ${businessID}`);
        const {
            data: [{ ...rest }],
        } = await this.findOne({ customerId, businessID });
        const { loadPoints } = this.InfluxService;
        const customerEntity = new CustomerEntity({ ...rest, ...updatedFields, customerId, businessID });
        const points = CustomerEntity.transformer(customerEntity, this.InfluxService);
        CustomerService.logger.log('Points', points);
        await loadPoints(`${process.env.STAGE}-config`, `enterprise`, points);
        return { message: 'Customer updated added', customerId: customerId };
    }
}

import { Point } from '@influxdata/influxdb-client';
import { Logger } from '@nestjs/common';
import { ApiHideProperty } from '@nestjs/swagger';
import { IsEmail, IsOptional } from 'class-validator';
import { InfluxService } from '../../influx/influx.service';
import { Address, StripePaymentChannelOptions, paymentChannel, TaxExempt } from '../dto/create-customer.dto';

export class CustomerEntity {
    private static readonly logger = new Logger(CustomerEntity.name);

    @ApiHideProperty()
    public static _measurement = 'CustomerConfig';

    /**
     * Unique identifier assigned by Enterprise
     * <br><br>
     * Example: `"e345f409-daca-4144-91d2-0a0f87c96581"`
     */
    public customerId: string;

    @ApiHideProperty()
    public businessID?: string;

    /**
     * The friendly, human-readable name of the customer
     */
    public customerName: string;

    /**
     * The payment channel associated with a customer
     */
    public paymentChannel: paymentChannel;

    /**
     * Customer email address
     */
    @IsEmail()
    @IsOptional()
    public email?: string;

    /**
     * Configuration options for the payment channel.
     * For Stripe payment, `stripeCustomerId` is required.
     * See example below.
     * <br><br>
     * Example `{"stripeCustomerId": "acct-xxxxxxxxxxxxxx"}`
     */
    public paymentChannelOptions?: StripePaymentChannelOptions;

    /**
     * Soft deletes a customer from the system.
     * @example true
     */
    @ApiHideProperty()
    public softDelete?: boolean;

    /**
     * The address of the customer
     *  */
    public address?: Address;

    /**
     * The VAT ID of the customer.
     * Every VAT identification number must begin with the code of the country concerned and
     * followed by a block of digits or characters.
     * <br><br>
     * Example `"GB VAT 123456789"`
     */
    public customerVatId?: string;

    /**
     * Whether the customer is exempt from paying taxes
     *
     * Default: `"none"`
     */
    public taxExempt?: TaxExempt;

    constructor({
        customerId,
        businessID = undefined,
        customerName,
        softDelete = undefined,
        paymentChannel,
        paymentChannelOptions,
        email = '',
        address,
        customerVatId,
        taxExempt = TaxExempt.none,
    }: CustomerEntity) {
        this.customerId = customerId;
        this.customerName = customerName;
        this.businessID = businessID;
        this.softDelete = softDelete;
        this.paymentChannel = paymentChannel;
        this.paymentChannelOptions = paymentChannelOptions;
        this.email = email;
        this.address = address;
        this.customerVatId = customerVatId;
        this.taxExempt = taxExempt;
    }
    static transformer(customerEntity: CustomerEntity, influxService: InfluxService): Array<Point> {
        const customerEntityPoint = influxService.getPoint(CustomerEntity._measurement);

        customerEntityPoint.tag('customerId', customerEntity.customerId);
        customerEntityPoint.tag('businessID', customerEntity.businessID);
        customerEntityPoint.tag('paymentChannel', customerEntity.paymentChannel);
        customerEntityPoint.tag('customerVatId', customerEntity.customerVatId);
        customerEntityPoint.tag('taxExempt', customerEntity.taxExempt);
        customerEntityPoint.tag('email', customerEntity.email);
        customerEntityPoint.stringField('customerName', customerEntity.customerName);
        if (customerEntity.address) {
            customerEntityPoint.tag('address', JSON.stringify(customerEntity.address));
        }

        if (customerEntity.paymentChannelOptions) {
            Object.keys(customerEntity.paymentChannelOptions).forEach((key) => {
                customerEntityPoint.tag(`paymentChannelOptions_${key}`, customerEntity.paymentChannelOptions[key]);
            });
        }
        if (customerEntity.softDelete) {
            customerEntityPoint.tag('softDelete', 'deleted');
        }
        // All Entity Transformers should return an array of points, keep logic consistent, even if there is only one element
        return [customerEntityPoint];
    }

    static dbModelToEntity(dbModel) {
        const { _value, customerId, paymentChannel, email, address, customerVatId, taxExempt, ...rest } = dbModel;

        const paymentChannelOptions = Object.keys(rest)
            .filter((key) => /paymentChannelOptions_/.test(key))
            .reduce((acc, key) => {
                acc[key.split('paymentChannelOptions_')[1]] = rest[key];
                return acc;
            }, {}) as CustomerEntity['paymentChannelOptions'];
        return new CustomerEntity({
            email,
            customerName: _value,
            customerId,
            paymentChannel,
            paymentChannelOptions,
            address: address ? JSON.parse(address) : {},
            customerVatId,
            taxExempt,
        });
    }
}
