import { Test, TestingModule } from '@nestjs/testing';
import { ConflictException } from '@nestjs/common';
import { CustomerService } from '../customer/customer.service';
import { DimensionsService } from '../dimensions/dimensions.service';
import { aggregationInterval } from '../dimensions/dto/create-dimension.dto';
import { InfluxService } from '../influx/influx.service';
import { MeasurementConfigService } from '../measurement-config/measurement-config.service';
import { OfferingService } from '../offering/offering.service';
import { ServicesService } from '../services/services.service';
import { UsageService } from './usage.service';

describe('UsageService', () => {
    const businessID = 'myCoolCorp';
    const customerId = 'e345f409-daca-4144-91d2-0a0f87c96581';
    const offeringId = 'ec2d4b40-2b0a-4e3b-9a55-6f6b3f5b2b7a';
    const dimension = {
        dimensionId: '12345',
        aggregationInterval: aggregationInterval.hour,
    };
    const offering = { offeringId, offeringName: 'myCoolOffering', dimensions: [dimension] };

    let service: UsageService;
    const mockGetAggregateUsageForDimension = jest.fn(() => [{ dimensionId: '12345', usage: [] }]);
    const mockCustomerFindOne = jest.fn(() => ({
        data: [{ customerId, offeringId, offering }],
        message: 'Found Customer',
    }));

    beforeEach(async () => {
        process.env.STAGE = 'unit-test';
        const module: TestingModule = await Test.createTestingModule({
            providers: [UsageService],
        })
            .useMocker((token) => {
                if (token === InfluxService) {
                    return { getAggregateUsageForDimension: mockGetAggregateUsageForDimension };
                }
                if (token === CustomerService) {
                    return { findOne: mockCustomerFindOne };
                }
                if (
                    token === MeasurementConfigService ||
                    token === DimensionsService ||
                    token === OfferingService ||
                    token === ServicesService
                ) {
                    return {};
                }
            })
            .compile();

        service = module.get<UsageService>(UsageService);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('should be defined', () => {
        expect(service).toBeDefined();
    });

    it('should resolve the dimensions from the offering of the customer and aggregate by customerId', async () => {
        const startTime = '2023-01-01T00:00:00.000Z';
        const endTime = '2023-01-02T00:00:00.000Z';
        await service.findUsageForCustomer({ customerId, businessID }, { startTime, endTime });

        expect(mockCustomerFindOne).toBeCalledWith({ customerId, businessID });
        expect(mockGetAggregateUsageForDimension).toBeCalledWith(
            expect.objectContaining({
                businessID,
                customerId,
                startTime,
                endTime,
                offeringDocument: expect.objectContaining({ dimensions: [dimension] }),
            })
        );
    });

    it('should override the aggregationInterval of every dimension when one is passed in', async () => {
        await service.findUsageForCustomer(
            { customerId, businessID },
            { aggregationInterval: aggregationInterval.none }
        );

        expect(mockGetAggregateUsageForDimension).toBeCalledWith(
            expect.objectContaining({
                offeringDocument: expect.objectContaining({
                    dimensions: [{ ...dimension, aggregationInterval: aggregationInterval.none }],
                }),
            })
        );
    });

    it('should reject the request with a conflict when the customer has no offering', async () => {
        mockCustomerFindOne.mockReturnValueOnce({
            data: [{ customerId, offeringId: undefined, offering: undefined }],
            message: 'Found Customer',
        } as never);

        await expect(service.findUsageForCustomer({ customerId, businessID })).rejects.toThrow(ConflictException);
        expect(mockGetAggregateUsageForDimension).not.toBeCalled();
    });
});

